TrajectoryModifier::TrajectoryModifier(const rclcpp::NodeOptions & options)
: Node("trajectory_modifier", options),
  param_listener_(
    std::make_unique<trajectory_modifier_params::ParamListener>(get_node_parameters_interface())),
  plugin_loader_(
    "autoware_trajectory_modifier",
    "autoware::trajectory_modifier::plugin::TrajectoryModifierPluginBase"),
  data_(std::make_shared<TrajectoryModifierData>(this))
{
  trajectories_sub_ = create_subscription<CandidateTrajectories>(
    "~/input/candidate_trajectories", 1,
    std::bind(&TrajectoryModifier::on_traj, this, std::placeholders::_1));
  trajectories_pub_ = create_publisher<CandidateTrajectories>("~/output/candidate_trajectories", 1);

  debug_processing_time_detail_pub_ = create_publisher<autoware_utils_debug::ProcessingTimeDetail>(
    "~/debug/processing_time_detail", 1);

  pub_processing_time_ = std::make_shared<autoware_utils_debug::DebugPublisher>(this, "~/debug");

  time_keeper_ =
    std::make_shared<autoware_utils_debug::TimeKeeper>(debug_processing_time_detail_pub_);

  params_ = param_listener_->get_params();

  // initialize plugins
  for (const auto & name : params_.plugin_names) {
    if (name.empty()) continue;
    load_plugin(name);
  }

  RCLCPP_INFO(get_logger(), "TrajectoryModifier initialized");
}

void TrajectoryModifier::load_plugin(const std::string & name)
{
  // Check if the plugin is already instantiated
  auto it = std::find_if(
    plugins_.begin(), plugins_.end(), [&](const auto & p) { return p->get_name() == name; });
  if (it != plugins_.end()) {
    RCLCPP_WARN(
      this->get_logger(), "The plugin '%s' is already in the plugins list.", name.c_str());
    return;
  }

  if (plugin_loader_.isClassAvailable(name)) {
    const auto plugin = plugin_loader_.createSharedInstance(name);
    plugin->initialize(name, this, time_keeper_, data_, params_);
    // register
    plugins_.push_back(plugin);
    RCLCPP_INFO(this->get_logger(), "The modifier plugin '%s' has been loaded", name.c_str());
    initialized_modifiers_ = true;
  } else {
    RCLCPP_ERROR(this->get_logger(), "The modifier plugin '%s' is not available", name.c_str());
  }
}

virtual bool isClassAvailable(const std::string & lookup_name);

/// Attempt to load the library containing a class with a given name.
/**
 * The counter for the library uses (refcount) is also incremented.
 *
 * \param lookup_name The lookup name of the class to load
 * \throws pluginlib::LibraryLoadException if the library for the

std::shared_ptr<T> createSharedInstance(const std::string & lookup_name);

/// Create an instance of a desired class.
/**
 * Implicitly calls loadLibraryForClass() to increment the library counter.
 *
 * Deleting the instance and calling unloadLibraryForClass() is automatically
 * handled by the unique pointer.

void initialize(
  std::string name, rclcpp::Node * node_ptr,
  const std::shared_ptr<autoware_utils_debug::TimeKeeper> time_keeper,
  const std::shared_ptr<TrajectoryModifierData> & data,
  [[maybe_unused]] const TrajectoryModifierParams & params)
{
  short_name_ = std::invoke([&name]() {
    const auto npos = name.find_last_of(':');
    return npos != std::string::npos ? name.substr(npos + 1) : name;
  });
  name_ = std::move(name);
  node_ptr_ = node_ptr;
  time_keeper_ = time_keeper;
  data_ = data;
  RCLCPP_DEBUG(
    node_ptr_->get_logger(), "instantiated TrajectoryModifierPluginBase: %s", name_.c_str());
  on_initialize(params);
}

void StopPointFixer::on_initialize(const TrajectoryModifierParams & params)
{
  const auto node_ptr = get_node_ptr();
  planning_factor_interface_ =
    std::make_unique<autoware::planning_factor_interface::PlanningFactorInterface>(
      node_ptr, "stop_point_fixer");

  params_ = params.stop_point_fixer;
  enabled_ = params.use_stop_point_fixer;
}
